function renderWithProviders(ui, { route = '/' } = {}) {
  window.history.pushState({}, '', route);

  return render(ui, {
    wrapper: ({ children }) => (
      <QueryClientProvider client={new QueryClient()}>
        <BrowserRouter>{children}</BrowserRouter>
      </QueryClientProvider>
    ),
  });
}
